import * as React from 'react';

import {
    safePolygon,
    useClick,
    useDismiss,
    useFloatingRootContext,
    useHover,
    useInteractions,
    useRole,
} from '@floating-ui/react';

import {useControlledState, useForkRef} from '../../hooks';
import {Popup} from '../Popup';
import type {PopupProps} from '../Popup';
import {useDefaultProps} from '../theme/useDefaultProps';
import type {AriaLabelingProps, DOMProps, QAProps} from '../types';
import {block} from '../utils/cn';
import {getElementRef} from '../utils/getElementRef';

export interface PopoverProps
    extends AriaLabelingProps,
        QAProps,
        DOMProps,
        Pick<
            PopupProps,
            | 'container'
            | 'disablePortal'
            | 'open'
            | 'onOpenChange'
            | 'strategy'
            | 'placement'
            | 'offset'
            | 'keepMounted'
            | 'hasArrow'
            | 'modal'
            | 'initialFocus'
            | 'returnFocus'
            | 'disableVisuallyHiddenDismiss'
            | 'zIndex'
        > {
    children:
        | ((props: Record<string, unknown>, ref: React.Ref<HTMLElement>) => React.ReactElement)
        | React.ReactElement;
    toggle?: boolean;
    disabled?: boolean;
    content?: React.ReactNode;
    trigger?: 'all' | 'click';
    openDelay?: number;
    closeDelay?: number;
    rest?: number;
    enableSafePolygon?: boolean;
}

const b = block('popover');
const DEFAULT_OPEN_DELAY = 500;
const DEFAULT_CLOSE_DELAY = 250;
const DEFAULT_REST = 0;

export function Popover(rawProps: PopoverProps) {
    const {
        children,
        open,
        onOpenChange,
        toggle = true,
        disabled,
        content,
        trigger = 'all',
        openDelay = DEFAULT_OPEN_DELAY,
        closeDelay = DEFAULT_CLOSE_DELAY,
        rest = DEFAULT_REST,
        enableSafePolygon,
        className,
        ...restProps
    } = useDefaultProps('Popover', rawProps);
    const [anchorElement, setAnchorElement] = React.useState<HTMLElement | null>(null);
    const [floatingElement, setFloatingElement] = React.useState<HTMLDivElement | null>(null);

    const [isOpen, setIsOpen] = useControlledState(open, false, onOpenChange);

    const context = useFloatingRootContext({
        open: isOpen && !disabled,
        onOpenChange: setIsOpen,
        elements: {
            reference: anchorElement,
            floating: floatingElement,
        },
    });

    const isHoverEnabled = trigger === 'all';

    const hover = useHover(context, {
        enabled: isHoverEnabled,
        delay: {open: openDelay, close: closeDelay},
        restMs: rest,
        move: false,
        handleClose: enableSafePolygon ? safePolygon() : undefined,
    });
    const click = useClick(context, {
        toggle,
