    wrap?: true | React.CSSProperties['flexWrap'];
    /**
     * display: inline-flex;
     */
    inline?: boolean;
    gap?: Space | MediaPartial<Space>;
    gapRow?: Space | MediaPartial<Space>;
    /**
     * @deprecated - use native gap property
