                                    emailNotifications: { ...current.emailNotifications, weeklyDigest: checked },
                                }))}
                            >
                                Дайджест за неделю
                            </Checkbox>
                        </Flex>
                        <Flex gap="3">
                            <Button view="action" size="m" onClick={handleSave}>Сохранить</Button>
                            <Button view="normal" size="m" onClick={resetFormData}>Отмена</Button>
                        </Flex>
                    </Flex>
                </section>
            </div>
        </main>
    );
}

